// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title MockStock: a test double for a tokenized stock, with an issuer blocklist like the real ones have.
/// Never deployed anywhere real; the tests give it a Uniswap v3 pool against WETH to exercise the Stock module end to end.
contract MockStock {
    string public name = "Mock Stock";
    string public symbol = "mSTK";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => bool) public blocked;
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    function mint(address to, uint256 value) external { totalSupply += value; balanceOf[to] += value; emit Transfer(address(0), to, value); }
    function setBlocked(address a, bool b) external { blocked[a] = b; }
    function transfer(address to, uint256 value) external returns (bool) { _move(msg.sender, to, value); return true; }
    function approve(address spender, uint256 value) external returns (bool) { allowance[msg.sender][spender] = value; emit Approval(msg.sender, spender, value); return true; }
    function transferFrom(address from, address to, uint256 value) external returns (bool) { uint256 a = allowance[from][msg.sender]; if (a != type(uint256).max) { require(a >= value, "allowance"); allowance[from][msg.sender] = a - value; } _move(from, to, value); return true; }
    function _move(address from, address to, uint256 value) internal { require(!blocked[to] && !blocked[from], "compliance"); require(balanceOf[from] >= value, "balance"); balanceOf[from] -= value; balanceOf[to] += value; emit Transfer(from, to, value); }
}
